/// Mounted only when the app is built with PSEUDO_LOCALE=true; listed before the real
/// delegate so `en_XA` finds it first.
class PseudoLocalizationsDelegate extends LocalizationsDelegate<AppLocalizations> {
  const PseudoLocalizationsDelegate();

  @override
  bool isSupported(Locale locale) =>
      locale.languageCode == 'en' && locale.countryCode == 'XA';

  @override
  Future<AppLocalizations> load(Locale locale) =>
      SynchronousFuture<AppLocalizations>(PseudoLocalizations());

  @override
  bool shouldReload(PseudoLocalizationsDelegate old) => false;
}
